function getCookie(t) { let e = t + "=", i = document.cookie.split(";"); for (let t = 0; t < i.length; t++) { let o = i[t]; for (; " " == o.charAt(0);)o = o.substring(1); if (0 == o.indexOf(e)) return o.substring(e.length, o.length) } return "" } if (localStorage.getItem("visite")) document.cookie = "visite=" + localStorage.getItem("visite") + ";"; else { import("https://openfpcdn.io/fingerprintjs/v4").then((t => t.load())).then((t => t.get())).then((t => localStorage.setItem("visite", t.visitorId)), document.cookie = "visite=result.visitorId;") }